WITH flattened_attrs AS (SELECT id, discounts, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT *, ROW_NUMBER() OVER (ORDER BY lowest_price, id) AS row_seq, LAST_VALUE(lowest_price, TRUE) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_lowest_price FROM flattened_attrs;
